#!/usr/bin/env python3
"""Independent reference generator: H2 / natural-gas blending (ISO 6976:2016 at 15/15 C, EN 16726 window). stdlib only. Generated by Claude."""
import json, os
# r2 23.10 (Claude): component values = ISO 6976:2016 Tables A.1-A.4 at 15/15 C (verified, see _ogh/core/r2_verify_iso6976.py).
from math import sqrt

R, T, p = 8.3144621, 288.15, 101325.0  # ISO 6976:2016 R
Mair, Zair, L = 28.96546, 0.999595, 44.431  # g/mol, -, kJ/mol (water at 15 C)

# id: (M g/mol, s at 15 C, Hs kJ/mol gross at 15 C, nC, nH)
DATA = {
    "ch4":  (16.04246, 0.04452,  891.51, 1, 4),
    "c2h6": (30.06904, 0.0919,  1562.14, 2, 6),
    "c3h8": (44.09562, 0.1344,  2221.10, 3, 8),
    "n2":   (28.0134,  0.0170,     0.0,  0, 0),
    "co2":  (44.0095,  0.0752,     0.0,  1, 0),
    "h2":   (2.01588, -0.01,     286.15, 0, 2),  # ISO 6976:2016 Table A.3 tabulates s(H2) = -0.01 (physical -sqrt(Z-1) = -0.0246)
}

def props(x):
    t = sum(x.values())
    x = {k: v / t for k, v in x.items()}
    S = lambda i: sum(v * DATA[k][i] for k, v in x.items())
    Z = 1.0 - S(1) ** 2
    M = S(0)
    Hs = S(2)
    Hi = Hs - L * sum(v * DATA[k][4] / 2.0 for k, v in x.items())
    V = Z * R * T / p                      # m3/mol
    Hs_vol, Hi_vol = Hs / 1000.0 / V, Hi / 1000.0 / V   # MJ/m3
    d = (M / Mair) * (Zair / Z)
    co2 = S(3) * 0.0440095 / (Hs * 1e-6) if Hs else float("nan")  # kg CO2/GJ gross
    return {
        "Z": Z, "M": M, "d": d,
        "Hs_vol": Hs_vol, "Hi_vol": Hi_vol,
        "Ws": Hs_vol / sqrt(d), "Wi": Hi_vol / sqrt(d),
        "Hs_mass": Hs / M, "Hi_mass": Hi / M,  # MJ/kg (kJ/g)
        "co2": co2,
    }

L = 44.431  # ISO 6976:2016 L(15 C), checked vs IAPWS-95 44.431
DEF = dict(ch4=.90,c2h6=.05,c3h8=.01,n2=.02,co2=.02,xH2=.10,E_MW=100.0,WsMin=46.44,WsMax=54.00,dMin=0.555,dMax=0.700,xH2Lim=0.20)
NG = ('ch4','c2h6','c3h8','n2','co2')
def mix(q, x):
    s = sum(q[k] for k in NG)
    m = {k: q[k]/s*(1-x) for k in NG}
    m['h2'] = x
    return m
def maxx(f, lim):
    if f(0) < lim: return 0
    if f(0.99) >= lim: return 0.99
    lo, hi = 0.0, 0.99
    for _ in range(80):
        m = (lo+hi)/2
        if f(m) >= lim: lo = m
        else: hi = m
    return lo
def solve(q):
    ng = props(mix(q, 0)); bl = props(mix(q, q['xH2'])); h = props({'h2': 1})
    r = dict(Hs_ng=ng['Hs_vol'], Hi_ng=ng['Hi_vol'], Ws_ng=ng['Ws'], Wi_ng=ng['Wi'], d_ng=ng['d'],
             Hs_bl=bl['Hs_vol'], Hi_bl=bl['Hi_vol'], Ws_bl=bl['Ws'], Wi_bl=bl['Wi'], d_bl=bl['d'],
             Hs_mass_bl=bl['Hs_mass'], Hi_mass_bl=bl['Hi_mass'])
    r['dWs_pct'] = 100*(r['Ws_bl']/r['Ws_ng']-1)
    r['dHs_pct'] = 100*(r['Hs_bl']/r['Hs_ng']-1)
    r['Vdot_ng'] = q['E_MW']/r['Hs_ng']; r['Vdot_bl'] = q['E_MW']/r['Hs_bl']
    r['Vratio'] = r['Vdot_bl']/r['Vdot_ng']; r['Vh2'] = q['xH2']*r['Vdot_bl']
    r['h2_energy_share_pct'] = 100*q['xH2']*h['Hs_vol']/r['Hs_bl']
    r['co2_ng'] = ng['co2']; r['co2_bl'] = bl['co2']
    r['co2_red_pct'] = 100*(1-r['co2_bl']/r['co2_ng'])
    W = maxx(lambda x: props(mix(q, x))['Ws'], q['WsMin'])
    D = maxx(lambda x: props(mix(q, x))['d'], q['dMin'])
    xm = min(W, D, q['xH2Lim'])
    r.update(xH2max_W=W, xH2max_d=D, xH2max=xm,
             governing='Wobbe' if xm == W else 'relative density' if xm == D else 'H2 limit')
    return r
RICH = dict(ch4=.85, c2h6=.09, c3h8=.03, n2=.01, co2=.02)
LEAN = dict(ch4=.965, c2h6=.02, c3h8=.005, n2=.005, co2=.005)
LGAS = dict(ch4=.81, c2h6=.03, c3h8=.005, n2=.14, co2=.015)
OVERRIDES = [
    ('default', {}), ('xH2_0', dict(xH2=0)), ('xH2_05', dict(xH2=.05)),
    ('xH2_20', dict(xH2=.2)), ('xH2_30', dict(xH2=.3)), ('xH2_50', dict(xH2=.5)),
    ('rich_ng', RICH), ('lean_ng', LEAN), ('l_gas', {**LGAS, 'xH2': .05}),
    ('WsMin_48', dict(WsMin=48)), ('dMin_05', dict(dMin=.5)), ('xH2Lim_05', dict(xH2Lim=.05)),
    ('E_MW_10', dict(E_MW=10)), ('rich_ng_xH2_25', {**RICH, 'xH2': .25}),
]
def main():
    cases = [{"id": i, "kind": "solve", "inputs": {**DEF, **o}, "ref": solve({**DEF, **o})} for i, o in OVERRIDES]
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "h2_ng_blending_ref.json")
    with open(out, "w") as f:
        json.dump({"tool": "h2_ng_blending", "generator": "bench-src/ref/gen_h2_ng_blending.py", "cases": cases}, f, indent=1)
    print(len(cases))
if __name__ == "__main__":
    main()
